  private val binder = object : IAnalyticsController.Stub() {
     override fun start() { /* init MPC */ }
     override fun stop() { /* shutdown */ }
     override fun setParams(p: Bundle) { /* update config */ }
  }
  override fun onBind(intent: Intent): IBinder = binder
